fixture_after.tests/tasks.test.mjs:
import test from 'node:test';
import assert from 'node:assert/strict';
import { listTasks } from '../src/tasks.mjs';
test('lists tasks without mutating the input', () => {
  const tasks = [{ id: 1, title: 'Ship the settings page', priority: 'high' }, { id: 2, title: 'Update the guide', priority: 'normal' }];
  assert.deepEqual(listTasks(tasks), tasks);
  assert.notEqual(listTasks(tasks), tasks);
});

test('defaults to all tasks for omitted or empty options and explicit all', () => {
  const tasks = [{ id: 1, priority: 'normal' }, { id: 2, priority: 'high' }, { id: 3 }];
  for (const options of [undefined, {}, { priority: undefined }, { priority: 'all' }]) {
    const result = listTasks(tasks, options);
    assert.deepEqual(result, tasks);
    assert.notEqual(result, tasks);
  }
});

test('filters high priority tasks in input order without mutating tasks or options', () => {
  const tasks = Object.freeze([
    Object.freeze({ id: 1, priority: 'high' }),
    Object.freeze({ id: 2, priority: 'normal' }),
    Object.freeze({ id: 3 }),
    Object.freeze({ id: 4, priority: 'high' }),
  ]);
  const options = Object.freeze({ priority: 'high' });
  const result = listTasks(tasks, options);
  assert.deepEqual(result, [tasks[0], tasks[3]]);
  assert.notEqual(result, tasks);
  result.pop();
  assert.equal(tasks.length, 4);
  assert.deepEqual(listTasks(tasks), tasks);
});

test('returns an empty list when there are no high priority tasks', () => {
  assert.deepEqual(listTasks([{ id: 1, priority: 'normal' }, { id: 2 }], { priority: 'high' }), []);
});

test('handles empty input for both filters', () => {
  const tasks = [];
  for (const priority of ['all', 'high']) {
    const result = listTasks(tasks, { priority });
    assert.deepEqual(result, []);
    assert.notEqual(result, tasks);
  }
});

test('preserves iterable input compatibility', () => {
  const high = { id: 1, priority: 'high' };
  const normal = { id: 2, priority: 'normal' };
  const tasks = new Set([high, normal]);
  assert.deepEqual(listTasks(tasks), [high, normal]);
  assert.deepEqual(listTasks(tasks, { priority: 'high' }), [high]);
});
